<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_role('Administrator');$pageTitle='Users & Roles';$activeMenu='users';if(isset($_GET['toggle'])){if(!hash_equals(csrf_token(),$_GET['token']??'')){http_response_code(419);exit('Invalid CSRF token.');}$id=(int)$_GET['toggle'];if($id===(int)current_user()['id']){flash('danger','You cannot disable your own active session.');}else{db()->prepare('UPDATE users SET is_active=1-is_active WHERE id=?')->execute([$id]);log_activity('UPDATE','Users','Toggled user #'.$id);flash('success','User status updated.');}redirect('users/index.php');}$users=db()->query("SELECT u.*,r.name role_name,d.name department FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN departments d ON d.id=u.department_id ORDER BY u.id")->fetchAll();$roles=db()->query('SELECT * FROM roles ORDER BY id')->fetchAll();require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><h1>Users & Roles</h1><p>Manage accounts, role assignments, departments and system access.</p></div><a class="btn btn-primary" href="<?=e(url('users/create.php'))?>"><i class="fa-solid fa-user-plus me-2"></i>Add User</a></div><div class="card-panel mb-4"><div class="card-body"><div class="table-responsive"><table class="table data-table"><thead><tr><th>Username</th><th>Name</th><th>Email</th><th>Role</th><th>Department</th><th>Status</th><th>Created</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td class="fw-semibold text-primary">@<?=e($u['username'])?></td><td><?=e($u['first_name'].' '.$u['last_name'])?></td><td><?=e($u['email'])?></td><td><span class="badge bg-primary-subtle text-primary"><?=e($u['role_name'])?></span></td><td><?=e($u['department']??'—')?></td><td><?=status_badge($u['is_active']?'Active':'Inactive')?></td><td><?=e(date('M d, Y',strtotime($u['created_at'])))?></td><td><div class="table-actions"><a class="btn btn-light border" href="<?=e(url('users/edit.php?id='.$u['id']))?>"><i class="fa-solid fa-pen"></i></a><a class="btn btn-light border" href="<?=e(url('users/index.php?toggle='.$u['id'].'&token='.csrf_token()))?>" title="Toggle status"><i class="fa-solid fa-power-off"></i></a></div></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="card-panel"><div class="card-head"><h2 class="section-title">Role Permission Matrix</h2></div><div class="card-body"><div class="table-responsive"><table class="table"><thead><tr><th>Role</th><th>Primary Access</th></tr></thead><tbody><?php $desc=['Administrator'=>'Full system access including administration','Finance Manager'=>'Budget, expenses, finance approvals and reports','Sales Manager'=>'Sales module, department approvals and reports','Marketing Manager'=>'Campaign module, department approvals and reports','Staff'=>'Dashboard and own expense requests','Viewer'=>'Reports only'];foreach($roles as $r):?><tr><td class="fw-semibold"><?=e($r['name'])?></td><td><?=e($desc[$r['name']]??'Configured role')?></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require ROOT_PATH.'/includes/footer.php';?>
